import { useState, useEffect } from 'react';

const SupermarketBillingApp = () => {
  const [productName, setProductName] = useState('');
  const [productPrice, setProductPrice] = useState('');
  const [productQuantity, setProductQuantity] = useState(1);
  const [products, setProducts] = useState([]);
  const [showInvoice, setShowInvoice] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date().toLocaleTimeString());
  const [currentDate] = useState(new Date().toLocaleDateString());

  // Update time every second
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date().toLocaleTimeString());
    }, 1000);
    return () => clearInterval(timer);
    const script = document.createElement("script");
    script.src = "https://checkout.razorpay.com/v1/checkout.js";
    script.async = true;
    document.body.appendChild(script);
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (productName && !isNaN(parseFloat(productPrice)) && productPrice > 0 && productQuantity > 0) {
      const price = parseFloat(productPrice);
      const quantity = parseInt(productQuantity);
      const itemTotal = price * quantity;
      const gst = itemTotal * 0.05;
      const totalPrice = itemTotal + gst;
      
      const newProduct = {
        id: products.length + 1,
        name: productName,
        price: price,
        quantity: quantity,
        itemTotal: itemTotal.toFixed(2),
        gst: gst.toFixed(2),
        totalPrice: totalPrice.toFixed(2)
      };
      
      setProducts([...products, newProduct]);
      setProductName('');
      setProductPrice('');
      setProductQuantity(1);
    }
  };

  const handlePayment = async () => {
    const res = await fetch("http://localhost:5000/create-order", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ amount: calculateTotal() * 100 }) // in paise
    });
  
    const data = await res.json();
  
    const options = {
      key: "rzp_test_Wcd8jGMtV9RLf8", // Replace with your Razorpay key
      amount: data.amount,
      currency: "INR",
      name: "Fresh Mart Supermarket",
      description: "Billing Payment",
      order_id: data.id,
      handler: function (response) {
        alert("Payment successful!");
        console.log(response);
      },
      prefill: {
        name: "Customer Name",
        email: "customer@example.com",
        contact: "9731497896"
      },
      theme: { color: "#6366F1" }
    };
  
    const rzp = new window.Razorpay(options);
    rzp.open();
  };

  const handleUndo = () => {
    setProducts(lastProducts); // restore last list
    setLastProducts([]);       // clear backup
  };
  

  const deleteProduct = (id) => {
    setProducts(products.filter(product => product.id !== id));
  };

  const calculateTotal = () => {
    return products.reduce((sum, product) => sum + parseFloat(product.totalPrice), 0).toFixed(2);
  };

  const calculateSubtotal = () => {
    return products.reduce((sum, product) => sum + parseFloat(product.itemTotal), 0).toFixed(2);
  };

  const calculateTotalGST = () => {
    return products.reduce((sum, product) => sum + parseFloat(product.gst), 0).toFixed(2);
  };

  const calculateTotalItems = () => {
    return products.reduce((sum, product) => sum + product.quantity, 0);
  };

  const calculateTotalProducts = () => {
    return products.length;
  };


  const printInvoice = () => {
    const invoiceContent = document.getElementById('invoiceContent').innerHTML;
    
    const printWindow = window.open('', '', 'width=600,height=600');
    printWindow.document.open();
    printWindow.document.write('<html><head><title>Supermarket Invoice</title>');
    printWindow.document.write('<style>');
    printWindow.document.write(`
      body { font-family: 'Arial', sans-serif; margin: 0; padding: 20px; color: #333; }
      .invoice-header { text-align: center; margin-bottom: 20px; }
      .company-name { font-size: 24px; font-weight: bold; color: #2c3e50; margin: 0; }
      .invoice-title { font-size: 18px; color: #7f8c8d; margin: 5px 0; }
      .invoice-details { display: flex; justify-content: space-between; margin-bottom: 20px; }
      .invoice-details div { font-size: 14px; }
      table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
      th { background-color: #f8f9fa; padding: 10px; text-align: left; border-bottom: 2px solid #ddd; }
      td { padding: 10px; text-align: left; border-bottom: 1px solid #ddd; }
      .total-section { text-align: right; margin-top: 20px; }
      .thank-you { text-align: center; margin-top: 30px; font-style: italic; color: #7f8c8d; }
      .gst-info { margin: 20px 0; font-size: 12px; color: #7f8c8d; }
    `);
    printWindow.document.write('</style></head><body>');
    printWindow.document.write(invoiceContent);
    printWindow.document.write('<div class="thank-you">Thank you for shopping with us!</div>');
    printWindow.document.write('</body></html>');
    printWindow.document.close();
    
    printWindow.print();
    printWindow.close();
  };

  const downloadInvoice = () => {
    // Create styled content for the invoice
    const invoiceNumber = `SM-${Math.floor(Math.random() * 10000)}`;
    const currentDateTime = new Date().toLocaleString();
    
    // Create HTML content for download
    let htmlContent = `
      <!DOCTYPE html>
      <html>
      <head>
          <title>Supermarket Invoice #${invoiceNumber}</title>
          <style>
              body { font-family: Arial, sans-serif; margin: 20px; color: #333; }
              .invoice-header { text-align: center; margin-bottom: 20px; }
              .company-name { font-size: 24px; font-weight: bold; color: #2c3e50; margin: 0; }
              .invoice-title { font-size: 18px; color: #7f8c8d; margin: 5px 0; }
              .invoice-details { display: flex; justify-content: space-between; margin-bottom: 20px; }
              .invoice-details div { font-size: 14px; }
              table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
              th { background-color: #f8f9fa; padding: 10px; text-align: left; border-bottom: 2px solid #ddd; }
              td { padding: 10px; text-align: left; border-bottom: 1px solid #ddd; }
              .total-section { text-align: right; margin-top: 20px; }
              .thank-you { text-align: center; margin-top: 30px; font-style: italic; color: #7f8c8d; }
              .right-align { text-align: right; }
              .center-align { text-align: center; }
          </style>
          <script src="https://checkout.razorpay.com/v1/checkout.js"></script>
      </head>
      <body>
          <div class="invoice-header">
              <h1 class="company-name">FRESH MART SUPERMARKET</h1>
              <p class="invoice-title">Tax Invoice</p>
          </div>
          
          <div class="invoice-details">
              <div>
                  <div><strong>Invoice #:</strong> ${invoiceNumber}</div>
                  <div><strong>Date:</strong> ${currentDate}</div>
                  <div><strong>Time:</strong> ${currentTime}</div>
              </div>
              <div style="text-align: right;">
                  <div><strong>Fresh Mart Supermarket Ltd.</strong></div>
                  <div>123 Market Street</div>
                  <div>Cityville, State 12345</div>
                  <div>Tel: (123) 456-7890</div>
                  <div>GSTIN: 22AAAAA0000A1Z5</div>
              </div>
          </div>
          
          <table>
              <thead>
                  <tr>
                      <th>#</th>
                      <th>Item Description</th>
                      <th class="right-align">Price</th>
                      <th class="center-align">Qty</th>
                      <th class="right-align">Amount</th>
                      <th class="right-align">GST (5%)</th>
                      <th class="right-align">Total</th>
                  </tr>
              </thead>
              <tbody>
    `;
    
    // Add all products to the table
    products.forEach((product, index) => {
      htmlContent += `
        <tr>
            <td>${index + 1}</td>
            <td>${product.name}</td>
            <td class="right-align">₹ ${product.price.toFixed(2)}</td>
            <td class="center-align">${product.quantity}</td>
            <td class="right-align">₹ ${product.itemTotal}</td>
            <td class="right-align">₹ ${product.gst}</td>
            <td class="right-align">₹ ${product.totalPrice}</td>
        </tr>
      `;
    });
    
    // Add summary and footer
    htmlContent += `
              </tbody>
          </table>
          
          <div class="total-section">
              <div style="display: flex; justify-content: space-between; border-top: 1px solid #ddd; padding-top: 10px;">
                  <div><strong>Subtotal:</strong></div>
                  <div>₹ ${calculateSubtotal()}</div>
              </div>
              <div style="display: flex; justify-content: space-between; padding-top: 5px;">
                  <div><strong>GST (5%):</strong></div>
                  <div>₹ ${calculateTotalGST()}</div>
              </div>
              <div style="display: flex; justify-content: space-between; padding-top: 10px; border-top: 1px solid #ddd; font-size: 18px; font-weight: bold;">
                  <div>Total:</div>
                  <div>₹ ${calculateTotal()}</div>
              </div>
          </div>
          
          <div style="margin-top: 30px; padding-top: 20px; border-top: 1px solid #ddd; font-size: 14px; color: #666;">
              <div>Payment Method: Cash</div>
              <div style="margin-top: 10px;">* This is a computer-generated invoice and does not require a physical signature.</div>
              <div class="thank-you">Thank you for shopping with Fresh Mart!</div>
          </div>
      </body>
      </html>
    `;
    
    // Create a Blob containing the HTML content
    const blob = new Blob([htmlContent], { type: 'text/html' });
    
    // Create a download link for the blob
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `supermarket-invoice-${invoiceNumber}.html`;
    document.body.appendChild(a);
    a.click();
    
    // Clean up
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 0);
  };

  return (
    <div className="bg-gray-50 min-h-screen">
      {/* Header */}
      <header className="bg-gradient-to-r from-green-600 to-green-800 text-white p-4 shadow-md">
        <div className="container mx-auto flex justify-between items-center">
          <div className="flex items-center">
            <svg className="w-8 h-8 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z"></path>
            </svg>
            <h1 className="text-2xl font-bold">Supermarket Billing System</h1>
          </div>
          <div className="text-sm">
            <div>{currentDate}</div>
            <div>{currentTime}</div>
          </div>
        </div>
      </header>

      <div className="container mx-auto py-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Product Form */}
          <div className="md:col-span-1">
            <div className="bg-white rounded-lg shadow-md p-6">
              <h2 className="text-xl font-semibold text-gray-800 mb-4 pb-2 border-b">Add Product</h2>
              <div>
                <div className="mb-4">
                  <label htmlFor="productName" className="block text-gray-700 mb-2">Product Name</label>
                  <input
                    type="text"
                    className="w-full px-4 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-green-600"
                    id="productName"
                    placeholder="Enter product name"
                    value={productName}
                    onChange={(e) => setProductName(e.target.value)}
                  />
                </div>
                <div className="mb-4">
                  <label htmlFor="productPrice" className="block text-gray-700 mb-2">Price (₹)</label>
                  <input
                    type="number"
                    step="0.01"
                    className="w-full px-4 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-green-600"
                    id="productPrice"
                    placeholder="Enter price"
                    value={productPrice}
                    onChange={(e) => setProductPrice(e.target.value)}
                  />
                </div>
                <div className="mb-4">
                  <label htmlFor="productQuantity" className="block text-gray-700 mb-2">Quantity</label>
                  <input
                    type="number"
                    min="1"
                    className="w-full px-4 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-green-600"
                    id="productQuantity"
                    placeholder="Enter quantity"
                    value={productQuantity}
                    onChange={(e) => setProductQuantity(e.target.value)}
                  />
                </div>
                <button 
                  onClick={handleSubmit}
                  className="w-full bg-green-600 hover:bg-green-700 text-white font-medium py-2 px-4 rounded transition duration-200"
                >
                  Add to Bill
                </button>
              </div>

              {/* Summary Card */}
              <div className="mt-6 bg-gray-50 p-4 rounded-lg border border-gray-200">
                <h3 className="font-medium text-gray-700 mb-2">Bill Summary</h3>
                <div className="flex justify-between mb-2">
                  <span className="text-gray-600">Total Products:</span>
                  <span className="font-medium">{calculateTotalProducts()}</span>
                </div>
                <div className="flex justify-between mb-2">
                  <span className="text-gray-600">Total Items:</span>
                  <span className="font-medium">{calculateTotalItems()}</span>
                </div>
                <div className="flex justify-between mb-2">
                  <span className="text-gray-600">Total Amount:</span>
                  <span className="font-medium">₹ {calculateTotal()}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">GST Included:</span>
                  <span className="font-medium">5%</span>
                </div>
              </div>
              <div className="flex items-center space-x-4">
  <button
    className="flex items-center bg-purple-600 hover:bg-purple-700 text-white px-7 py-2 rounded"
    onClick={handlePayment}
  >
    <svg
      className="w-4 h-4 mr-2"
      fill="none"
      stroke="currentColor"
      viewBox="0 0 24 24"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth="2"
        d="M3 7h18M3 10h18M5 14h2M9 14h2M3 5a2 2 0 012-2h14a2 2 0 012 2v14a2 2 0 01-2 2H5a2 2 0 01-2-2V5z"
      />
    </svg>
    Pay Online
  </button>

  <button
    className="flex items-center bg-blue-600 hover:bg-blue-700 text-white px-7 py-2 rounded"
    onClick={() => setShowInvoice(true)}
    disabled={products.length === 0}
  >
    <svg
      className="w-5 h-5 mr-2"
      fill="none"
      stroke="currentColor"
      viewBox="0 0 24 24"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth="2"
        d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
      />
    </svg>
    Generate Invoice
  </button>
</div>

            </div>
          </div>
          
          {/* Product Table */}
          <div className="md:col-span-2">
            <div className="bg-white rounded-lg shadow-md overflow-hidden">
            <div className="p-6 border-b flex justify-between items-center">
            <h2 className="text-xl font-semibold text-gray-800">Current Bill</h2>
            <button
              className="flex items-center bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-full shadow-md transition duration-200 ease-in-out disabled:opacity-50"
              onClick={() => setProducts([])}
              disabled={products.length === 0}
            >
            <svg
              className="w-5 h-5 mr-2"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              viewBox="0 0 24 24"
              xmlns="http://www.w3.org/2000/svg"
            >
            <path d="M3 6h18M9 6V4a1 1 0 011-1h4a1 1 0 011 1v2m2 0v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6h14z" />
            </svg>
            Clear All
            </button>
            </div>

              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">#</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Product</th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Price</th>
                      <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">Qty</th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Amount</th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">GST (5%)</th>
                      <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Total</th>
                      <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">Action</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {products.map((product) => (
                      <tr key={product.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{product.id}</td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{product.name}</td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 text-right">₹ {product.price.toFixed(2)}</td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 text-center">{product.quantity}</td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 text-right">₹ {product.itemTotal}</td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 text-right">₹ {product.gst}</td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900 text-right">₹ {product.totalPrice}</td>
                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                          <button 
                            className="text-red-600 hover:text-red-900"
                            onClick={() => deleteProduct(product.id)}
                          >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path>
                            </svg>
                          </button>
                        </td>
                      </tr>
                    ))}
                    {products.length === 0 && (
                      <tr>
                        <td colSpan="8" className="px-6 py-10 text-center text-gray-500">
                          No products added yet. Add a product to start your bill.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
              
              {products.length > 0 && (
                <div className="px-6 py-4 bg-gray-50 border-t border-gray-200">
                  <div className="flex justify-end">
                    <div className="text-right">
                      <div className="text-sm text-gray-500">Total Products: {calculateTotalProducts()}</div>
                      <div className="text-sm text-gray-500">Total Items: {calculateTotalItems()}</div>
                      <div className="text-xl font-bold text-gray-800 mt-1">Total: ₹ {calculateTotal()}</div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
      
      {/* Invoice Modal */}
      {showInvoice && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg w-4/5 max-w-4xl max-h-screen overflow-y-auto">
            <div className="flex justify-between items-center p-6 border-b">
              <h5 className="text-xl font-bold text-gray-800">Invoice</h5>
              <button 
                type="button" 
                className="text-gray-400 hover:text-gray-500" 
                onClick={() => setShowInvoice(false)}
              >
                <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <div className="p-6">
              <div id="invoiceContent">
                <div className="invoice-header">
                  <h1 className="company-name">FRESH MART SUPERMARKET</h1>
                  <p className="invoice-title">Tax Invoice</p>
                </div>
                
                <div className="invoice-details flex justify-between mb-6">
                  <div>
                    <div className="font-semibold">Invoice #: SM-{Math.floor(Math.random() * 10000)}</div>
                    <div>Date: {currentDate}</div>
                    <div>Time: {currentTime}</div>
                  </div>
                  <div className="text-right">
                    <div className="font-semibold mb-2">Fresh Mart Supermarket Ltd.</div>
                    <div>123 Market Street</div>
                    <div>Cityville, State 12345</div>
                    <div>Tel: (123) 456-7890</div>
                    <div>GSTIN: 22AAAAA0000A1Z5</div>
                  </div>
                </div>
                
                <table className="w-full">
                  <thead className="bg-gray-100">
                    <tr>
                      <th className="text-left p-2 border-y-2 border-gray-300">#</th>
                      <th className="text-left p-2 border-y-2 border-gray-300">Item Description</th>
                      <th className="text-right p-2 border-y-2 border-gray-300">Unit Price</th>
                      <th className="text-center p-2 border-y-2 border-gray-300">Qty</th>
                      <th className="text-right p-2 border-y-2 border-gray-300">Amount</th>
                      <th className="text-right p-2 border-y-2 border-gray-300">GST (5%)</th>
                      <th className="text-right p-2 border-y-2 border-gray-300">Total</th>
                    </tr>
                  </thead>
                  <tbody>
                    {products.map((product, index) => (
                      <tr key={product.id} className="border-b border-gray-200">
                        <td className="p-2">{index + 1}</td>
                        <td className="p-2">{product.name}</td>
                        <td className="p-2 text-right">₹ {product.price.toFixed(2)}</td>
                        <td className="p-2 text-center">{product.quantity}</td>
                        <td className="p-2 text-right">₹ {product.itemTotal}</td>
                        <td className="p-2 text-right">₹ {product.gst}</td>
                        <td className="p-2 text-right">₹ {product.totalPrice}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                
                <div className="mt-6 text-right">
                  <div className="flex justify-between border-t border-gray-200 pt-2">
                    <div className="font-medium">Subtotal:</div>
                    <div>₹ {calculateSubtotal()}</div>
                  </div>
                  <div className="flex justify-between pt-1">
                    <div className="font-medium">GST (5%):</div>
                    <div>₹ {calculateTotalGST()}</div>
                  </div>
                  <div className="flex justify-between pt-2 border-t border-gray-200 text-xl font-bold">
                    <div>Total:</div>
                    <div>₹ {calculateTotal()}</div>
                  </div>
                </div>
                
                <div className="mt-8 pt-4 border-t border-gray-200 text-sm text-gray-600">
                  <div>Payment Method: Cash</div>
                  <div className="mt-2">* This is a computer-generated invoice and does not require a physical signature.</div>
                  <div className="mt-4 text-center font-medium">Thank you for shopping with Fresh Mart!</div>
                </div>
              </div>
            </div>
            <div className="flex justify-end p-6 border-t">
              <button 
                className="bg-gray-200 hover:bg-gray-300 px-4 py-2 rounded mr-2"
                onClick={() => setShowInvoice(false)}
              >
                Close
              </button>
              <button 
                className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded flex items-center"
                onClick={printInvoice}
              >
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path>
                </svg>
                Print Invoice
              </button>

            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SupermarketBillingApp;
